// Request
public record GetUserQuery(int Id) : IRequest<User?>;

public class GetUserHandler : IRequestHandler<GetUserQuery, User?>
{
    public async Task<User?> Handle(GetUserQuery request, CancellationToken ct)
    {
        return await _db.Users.FindAsync(new object[] { request.Id }, ct);
    }
}

// Notification
public record UserCreatedNotification(User User) : INotification;

public class EmailNotifier : INotificationHandler<UserCreatedNotification>
{
    public async Task Handle(UserCreatedNotification notification, CancellationToken ct)
    {
        Console.WriteLine($"Email sent to {notification.User.Email}");
    }
}
